#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=9

# ── 共用設定與小工具（票 02 專用）────────────────────────────────────────
DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT="$(cd "$DIR/../../.." && pwd)"
PROBE="$DIR/VddProbe/bin/Release/net48/VddProbe.exe"
APP="$ROOT/release/AutoDisplayMode.exe"
DRV="$ROOT/release/drivers/sudovda"
LOGS="$DIR/logs"
ENV_FILE="$ROOT/.scratch/remote-mode/prototype-results.env"
mkdir -p "$LOGS"

winpath() { cygpath -w "$1"; }

# ui_driver KEY "按鈕" "預期狀態"：請使用者在程式的設定視窗按下驅動按鈕（手動測試成品的介面），記錄結果
ui_driver() {
  step "在工作列的 Auto Display Mode 圖示按右鍵 → 設定 → 「一般設定」分頁。"
  step "按「$2」，跳出 UAC 時按「是」。"
  step "等設定視窗上的驅動狀態更新。"
  pause "完成後按 Enter"
  yesno "$1_OK" "設定視窗顯示「$3」了嗎？"
  local note="$1_NOTE"
  ask "$note" "過程中有錯誤訊息、卡住、或其他奇怪的地方嗎？（沒有就直接按 Enter）："
  write_env "$note" "${!note:-}"
}

# start_bg LOG ARGS...：在背景執行 VddProbe，PID 存進 BG_PID
start_bg() { local log="$1"; shift; : > "$log"; "$PROBE" "$@" > "$log" 2>&1 & BG_PID=$!; }
# start_watch LOG SECONDS：在背景監看虛擬螢幕何時消失，PID 存進 WATCH_PID
start_watch() { : > "$1"; "$PROBE" watch "$2" > "$1" 2>&1 & WATCH_PID=$!; }
# kill_hard PID：像工作管理員「結束工作」一樣強制結束背景的 VddProbe
kill_hard() { local w; w=$(cat "/proc/$1/winpid" 2>/dev/null) && taskkill //F //PID "$w" >/dev/null 2>&1 || true; }
# wait_for FILE PATTERN SECONDS
wait_for() { local i; for ((i = 0; i < $3 * 5; i++)); do grep -q "$2" "$1" 2>/dev/null && return 0; sleep 0.2; done; return 1; }
# value FILE PATTERN：取出最後一個符合的片段
value() { grep -o "$2" "$1" 2>/dev/null | tail -n1 || true; }
lines() { wc -l < "$1" | tr -d ' '; }
# sum_input FILE FROMLINE：彙總 FROMLINE 之後的鍵盤滑鼠輸入（實體／注入）
sum_input() {
  tail -n +"$(($2 + 1))" "$1" | grep -o 'mouse physical=[0-9]* injected=[0-9]* | keyboard physical=[0-9]* injected=[0-9]*' |
    awk -F'[= |]+' '{mp+=$3; mi+=$5; kp+=$8; ki+=$10} END {printf "mouse physical=%d injected=%d, keyboard physical=%d injected=%d", mp, mi, kp, ki}'
}
# yesno KEY "問題"：y/N 的答案寫成 yes/no
yesno() { if confirm "$2"; then write_env "$1" yes; else write_env "$1" no; fi; }
flush_input() { while read -r -t 0.1 -n 1000 _; do :; done; }
countdown() { local i; for ((i = $1; i > 0; i--)); do printf '\r  %s%s 秒…%s ' "$DIM" "$i" "$RESET"; sleep 1; done; printf '\r\n'; }
display_devices() {
  powershell.exe -NoProfile -Command 'Get-PnpDevice -Class Display | Sort-Object FriendlyName | ForEach-Object { "$($_.Status) $($_.FriendlyName)" }' | tr -d '\r'
}
indent() { sed 's/^/    /' "$1"; }

banner "票 02：虛擬螢幕原型實測"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "準備"
say "這個精靈帶你完成票 02 中需要你本人的部分，大約 30～45 分鐘。"
say "結果會寫進 .scratch/remote-mode/prototype-results.env，紀錄檔在 .scratch/remote-mode/prototype/logs/。"
echo
step "準備一台手機或筆電，裝好 Chrome 遠端桌面，確認能連到這台電腦。"
step "存好手上的工作：測試中實體螢幕會變黑好幾次。"
step "實體螢幕變黑時，這個視窗會跑到虛擬螢幕上，要用手機遠端才看得到。"
echo
warn "萬一實體螢幕一直黑、手機也連不上：按 Win+P，選「延伸」或「僅電腦螢幕」。"
warn "還是不行就重新開機：開機時不會有虛擬螢幕，實體螢幕一定會亮。"
echo
[[ -x "$PROBE" ]] || { warn "找不到 VddProbe.exe，請先請 Claude 編譯：$PROBE"; exit 1; }
[[ -f "$APP" ]] || { warn "找不到程式：$APP（先執行 build.bat）"; exit 1; }
[[ -f "$DRV/x64/SudoVDA.inf" ]] || { warn "找不到驅動檔：$DRV/x64（先執行 build.bat）"; exit 1; }
step "確認 release\\AutoDisplayMode.exe（新版、有「安裝驅動」按鈕的版本）正在執行。"
open_url "https://remotedesktop.google.com/access"
step "在開啟的頁面確認這台電腦顯示為「線上」。"
ask CRD_CLIENT "你會用什麼裝置連進來（例如 iPhone、Android 手機、筆電）："
write_env CRD_CLIENT "$CRD_CLIENT"
confirm "都準備好了，要開始嗎？" || exit 0

# ── 2 ────────────────────────────────────────────────────────────────────
stage "安裝驅動（用程式的介面）"
say "這一步同時手動測試程式的「安裝驅動」功能。"
display_devices > "$LOGS/display-devices-before.txt"
ui_driver UI_INSTALL "安裝驅動" "已安裝"
"$PROBE" status > "$LOGS/status-after-install.txt" 2>&1 || true
indent "$LOGS/status-after-install.txt"
write_env DRIVER_INTERFACE "$(value "$LOGS/status-after-install.txt" 'INTERFACE=.*' | cut -d= -f2-)"
write_env DRIVER_WATCHDOG "$(value "$LOGS/status-after-install.txt" 'WATCHDOG_TIMEOUT=[0-9]*s' | cut -d= -f2)"
yesno DRIVER_INSTALL_EXTRA_PROMPT "安裝時除了 UAC，有跳出其他視窗（例如「Windows 安全性：是否要安裝此裝置軟體」）嗎？"
display_devices > "$LOGS/display-devices-after-install.txt"
say "顯示介面卡（安裝後）："
indent "$LOGS/display-devices-after-install.txt"
if diff <(grep -v -i sudomaker "$LOGS/display-devices-before.txt") <(grep -v -i sudomaker "$LOGS/display-devices-after-install.txt") >/dev/null; then
  write_env OTHER_VIRTUAL_UNCHANGED_AFTER_INSTALL yes
else
  write_env OTHER_VIRTUAL_UNCHANGED_AFTER_INSTALL no
fi
pause

# ── 3 ────────────────────────────────────────────────────────────────────
stage "建立虛擬螢幕（一般權限）"
say "以一般權限建立一台 1920×1080@60 的虛擬螢幕，實體螢幕維持開啟。"
start_bg "$LOGS/hold.log" hold 1920 1080 60
HOLD_PID=$BG_PID
wait_for "$LOGS/hold.log" 'RUNNING\|ERROR' 30 || true
indent "$LOGS/hold.log"
if grep -q 'ADDED' "$LOGS/hold.log"; then write_env ADD_AS_USER yes; else write_env ADD_AS_USER no; fi
write_env VIRTUAL_APPEARED "$(value "$LOGS/hold.log" 'VIRTUAL_APPEARED=[A-Za-z]* after [0-9]*ms')"
write_env VIRTUAL_MODES "$(value "$LOGS/hold.log" 'MODES([0-9]*)=.*')"
"$PROBE" detect > "$LOGS/detect-with-virtual.txt" 2>&1 || true
write_env VIRTUAL_ADAPTER_HWID "$(grep -i -o '=> .*sudomaker[^ ]*' "$LOGS/detect-with-virtual.txt" | head -n1 || true)"
open_url "ms-settings:display"
step "在「設定 → 系統 → 顯示器」看看是否多了一台螢幕（名稱可能是 AutoDisplay）。"
yesno VIRTUAL_VISIBLE_IN_SETTINGS "有看到多出來的螢幕嗎？"

# ── 4 ────────────────────────────────────────────────────────────────────
stage "心跳保險"
say "精靈會強制結束測試工具（模擬閃退），量虛擬螢幕幾秒後被驅動自動移除。"
say "這一步不用做任何事，看著就好。"
start_watch "$LOGS/watch-hold.log" 5
sleep 1
kill_hard "$HOLD_PID"
say "已強制結束，等待中…"
wait "$WATCH_PID" 2>/dev/null || true
indent "$LOGS/watch-hold.log"
write_env WATCHDOG_GONE_MS "$(value "$LOGS/watch-hold.log" 'VIRTUAL_GONE after [0-9]*ms' | grep -o '[0-9]*' || true)"
pause

# ── 5 ────────────────────────────────────────────────────────────────────
stage "只剩虛擬螢幕＋Chrome 遠端桌面"
say "接下來實體螢幕會全部變黑，只剩虛擬螢幕，這個視窗也會移到虛擬螢幕上。"
say "請先把下面的步驟看完："
step "1. 按 Enter 後，用手機的 Chrome 遠端桌面連進這台電腦，你會在畫面上看到這個視窗。"
step "2. 依照視窗上的指示操作（大約 5 分鐘）。"
step "3. 結束時精靈會還原實體螢幕。"
warn "5 分鐘內沒回應，精靈會自動還原實體螢幕。"
pause "看完請按 Enter 開始"
start_bg "$LOGS/solo.log" solo 1920 1080 60
SOLO_PID=$BG_PID
wait_for "$LOGS/solo.log" 'RUNNING\|ERROR' 40 || true
if grep -q ERROR "$LOGS/solo.log"; then
  indent "$LOGS/solo.log"; warn "建立失敗，跳過這一步。"; write_env SOLO_STARTED no
  "$PROBE" stop >/dev/null 2>&1 || true
  pause
else
  write_env SOLO_STARTED yes
  write_env SOLO_ACTIVE "$(value "$LOGS/solo.log" 'SOLO result=.*')"
  _clear
  printf '\n%s  只剩虛擬螢幕了。用手機連進來後，在這裡繼續。%s\n\n' "$BOLD" "$RESET"
  printf '  %s? 連上了，看得到這個視窗嗎？ [y/N]%s ' "$YELLOW" "$RESET"
  reply=""
  if read -r -t 300 reply; then
    if [[ "$reply" =~ ^[Yy] ]]; then write_env CRD_SEES_VIRTUAL yes; else write_env CRD_SEES_VIRTUAL no; fi

    echo
    step "在 Chrome 遠端桌面的選單（側邊面板）開啟「調整桌面大小以符合」，觀察畫面。"
    pause "調整後按 Enter"
    "$PROBE" status > "$LOGS/status-after-resize.txt" 2>&1 || true
    write_env CRD_RESIZE_ACTIVE "$(value "$LOGS/status-after-resize.txt" 'ACTIVE=.*' | cut -d= -f2-)"
    ask CRD_RESIZE_NOTE "畫面變成符合手機的大小了嗎？簡單描述："
    write_env CRD_RESIZE_NOTE "$CRD_RESIZE_NOTE"

    echo
    step "接下來 10 秒，在手機上移動游標、點桌面空白處，並按幾下 Shift。"
    pause "準備好按 Enter"
    mark=$(lines "$LOGS/solo.log"); countdown 10; flush_input
    write_env REMOTE_INPUT "$(sum_input "$LOGS/solo.log" "$mark")"
    say "記錄到：$REMOTE_INPUT"

    echo
    step "接下來 20 秒，走到電腦前，動一下實體滑鼠、按幾下實體鍵盤的 Shift（螢幕是黑的沒關係），再回到手機。"
    pause "準備走過去時按 Enter"
    mark=$(lines "$LOGS/solo.log"); countdown 20; flush_input
    write_env LOCAL_INPUT "$(sum_input "$LOGS/solo.log" "$mark")"
    say "記錄到：$LOCAL_INPUT"
    pause "按 Enter 還原實體螢幕"
  else
    write_env CRD_SEES_VIRTUAL timeout
    echo
  fi
  "$PROBE" stop >/dev/null 2>&1 || true
  wait "$SOLO_PID" 2>/dev/null || true
  { grep -v INPUT "$LOGS/solo.log" || true; } | sed "s/^/    /"
  write_env SOLO_RESTORE "$(value "$LOGS/solo.log" 'RESTORE result=.*')"
  yesno SOLO_RESTORE_OK "實體螢幕都恢復成原本的樣子了嗎？"
fi

# ── 6 ────────────────────────────────────────────────────────────────────
stage "意外結束時 Windows 怎麼還原"
say "再一次只剩虛擬螢幕。約 10 秒後精靈會強制結束測試工具（模擬閃退），不讓它還原。"
say "請坐在電腦前看實體螢幕：會不會自己亮回來？亮回來時是不是原本的配置？大約幾秒？"
warn "如果 30 秒後還是全黑，按 Win+P 選「延伸」。這個視窗之後會出現在亮著的螢幕上。"
pause "看完請按 Enter 開始"
start_bg "$LOGS/solo-kill.log" solo 1920 1080 60
SOLO_KILL_PID=$BG_PID
wait_for "$LOGS/solo-kill.log" 'RUNNING\|ERROR' 40 || true
sleep 10
start_watch "$LOGS/watch-solo-kill.log" 20
sleep 1
kill_hard "$SOLO_KILL_PID"
wait "$WATCH_PID" 2>/dev/null || true
_clear
printf '\n'
indent "$LOGS/watch-solo-kill.log"
write_env KILL_BEFORE_ACTIVE "$(value "$LOGS/solo-kill.log" 'BEFORE ACTIVE=.*' | cut -d= -f2-)"
write_env KILL_GONE_MS "$(value "$LOGS/watch-solo-kill.log" 'VIRTUAL_GONE after [0-9]*ms' | grep -o '[0-9]*' || true)"
write_env KILL_FINAL_ACTIVE "$(value "$LOGS/watch-solo-kill.log" 'FINAL ACTIVE=.*' | cut -d= -f2-)"
ask WINDOWS_RESTORE_NOTE "實體螢幕怎麼變化？（例如：約 N 秒後恢復原本配置／只亮一台／一直黑要按 Win+P）："
write_env WINDOWS_RESTORE_NOTE "$WINDOWS_RESTORE_NOTE"

# ── 7 ────────────────────────────────────────────────────────────────────
stage "睡眠喚醒"
say "建立虛擬螢幕（實體螢幕維持開啟），再讓電腦睡眠、喚醒，看虛擬螢幕還在不在。"
start_bg "$LOGS/hold-sleep.log" hold 1920 1080 60
SLEEP_PID=$BG_PID
wait_for "$LOGS/hold-sleep.log" 'RUNNING\|ERROR' 30 || true
step "開始 → 電源 → 睡眠。等螢幕全暗約 30 秒後，按鍵盤或滑鼠喚醒並登入。"
pause "喚醒回來後按 Enter"
sleep 3
"$PROBE" status > "$LOGS/status-after-sleep.txt" 2>&1 || true
write_env SLEEP_VIRTUAL_PRESENT "$(value "$LOGS/status-after-sleep.txt" 'VIRTUAL_PRESENT=[A-Za-z]*' | cut -d= -f2)"
if grep -q 'PING FAILED' "$LOGS/hold-sleep.log"; then write_env SLEEP_PING_FAILED yes; else write_env SLEEP_PING_FAILED no; fi
"$PROBE" stop >/dev/null 2>&1 || true
wait "$SLEEP_PID" 2>/dev/null || true
pause

# ── 8 ────────────────────────────────────────────────────────────────────
stage "移除驅動（用程式的介面）"
say "手動測試程式的「移除驅動」功能：裝置、驅動套件與憑證都要移除乾淨。"
ui_driver UI_UNINSTALL "移除驅動" "未安裝"
"$PROBE" status > "$LOGS/status-after-uninstall.txt" 2>&1 || true
indent "$LOGS/status-after-uninstall.txt"
write_env UNINSTALL_DEVICE_COUNT "$(value "$LOGS/status-after-uninstall.txt" 'DEVICE_COUNT=[0-9]*' | cut -d= -f2)"
write_env UNINSTALL_CERT_ROOT "$(value "$LOGS/status-after-uninstall.txt" 'CERT_Root=.*' | cut -d= -f2-)"
write_env UNINSTALL_CERT_PUBLISHER "$(value "$LOGS/status-after-uninstall.txt" 'CERT_TrustedPublisher=.*' | cut -d= -f2-)"
write_env UNINSTALL_PACKAGES "$(value "$LOGS/status-after-uninstall.txt" 'PACKAGES=.*' | cut -d= -f2-)"
display_devices > "$LOGS/display-devices-after-uninstall.txt"
if diff "$LOGS/display-devices-before.txt" "$LOGS/display-devices-after-uninstall.txt" >/dev/null; then
  write_env DISPLAY_DEVICES_SAME_AS_BEFORE yes
else
  write_env DISPLAY_DEVICES_SAME_AS_BEFORE no
fi
pause

# ── 9 ────────────────────────────────────────────────────────────────────
stage "重新安裝（用程式的介面）"
say "重新裝回驅動，留給票 03 開發使用；同時確認移除後可以再次安裝。"
ui_driver UI_REINSTALL "安裝驅動" "已安裝"
"$PROBE" status > "$LOGS/status-after-reinstall.txt" 2>&1 || true
indent "$LOGS/status-after-reinstall.txt"
write_env REINSTALL_INTERFACE "$(value "$LOGS/status-after-reinstall.txt" 'INTERFACE=.*' | cut -d= -f2-)"
say "全部完成！回到 Claude 對話說「精靈跑完了」，Claude 會讀取結果整理到票 02。"
pause

finish
}

run_wizard "$@"; exit
